/* ===================== BÀI 51 · Timeout, interlock và lỗi ===================== */
/* Bài 51 · Timeout, interlock và lỗi (AMTS-EMB-001-M13-L03, MC51-051) — sinh bởi tools/author/mcu8051/l51.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const P51=[{"label":"Ví dụ: Chờ cảm biến có thời hạn","code":"; Ví dụ 1: chờ cảm biến có thời hạn. Mỗi vòng BUOC = 1 tick\n; Van: P1.0 đẩy, P1.1 lùi (0 = bật) · P1.7 đèn lỗi\nSTATE   DATA    30H                     ; 0 CHỜ 1 ĐẨY 2 LÙI 3 LỖI\nTMR     DATA    31H                     ; số tick còn được chờ\nERR     DATA    32H                     ; 1 thiếu S_CUOI, 2 thiếu S_DAU\nPOS     DATA    33H                     ; vị trí xi lanh 0..4 (mô hình)\nDEM     DATA    34H                     ; số phôi đã xong\nHONG    BIT     20H.0                   ; tiêm lỗi: cảm biến cuối hỏng\nSTART   BIT     20H.1                   ; sự kiện nút START\nSCUOI   BIT     20H.2\nSDAU    BIT     20H.3\n        ORG     0000H\n        CLR     HONG                    ; ví dụ 2: SETB HONG\n        SETB    START                   ; người vận hành nhấn START\n        MOV     R7,#16                  ; chạy 16 tick\nBUOC:   ACALL   MOHINH                  ; cập nhật mô hình + cảm biến\n        MOV     A,STATE\n        CJNE    A,#1,K2\n        JB      SCUOI,D_OK              ; ĐẨY: chờ S_CUOI có thời hạn\n        DJNZ    TMR,TIEP\n        MOV     ERR,#1                  ; quá hạn: thiếu S_CUOI\n        SJMP    LOI\nD_OK:   MOV     STATE,#2                ; sang LÙI\n        INC     DEM                     ; phôi đã được đẩy ra\n        MOV     P1,#0FDH                ; đóng đẩy, mở lùi\n        MOV     TMR,#8\n        SJMP    TIEP\nK2:     CJNE    A,#2,K0\n        JB      SDAU,L_OK               ; LÙI: chờ S_DAU có thời hạn\n        DJNZ    TMR,TIEP\n        MOV     ERR,#2\n        SJMP    LOI\nL_OK:   MOV     STATE,#0\n        MOV     P1,#0FFH\n        SJMP    TIEP\nK0:     JNZ     TIEP                    ; LỖI: giữ nguyên, van đã tắt\n        JBC     START,BAT               ; CHỜ: tiêu thụ sự kiện START\n        SJMP    TIEP\nBAT:    MOV     STATE,#1\n        MOV     P1,#0FEH                ; mở van đẩy\n        MOV     TMR,#8                  ; bình thường cần 4 tick\n        SJMP    TIEP\nLOI:    MOV     STATE,#3\n        MOV     P1,#7FH                 ; tắt hai van, bật đèn lỗi\nTIEP:   DJNZ    R7,BUOC\n        SJMP    $\n; --- mô hình xi lanh (giả lập nhà máy, không có trên chip) ---\nMOHINH: MOV     A,POS\n        JB      P1.0,M_LUI              ; van đẩy bật thì ra thêm 1 nấc\n        CJNE    A,#4,$+3\n        ADDC    A,#0                    ; POS < 4 (CY = 1): POS + 1\n        SJMP    M_CB\nM_LUI:  JB      P1.1,M_CB               ; van lùi bật thì về 1 nấc\n        JZ      M_CB\n        DEC     A\nM_CB:   MOV     POS,A\n        CJNE    A,#4,$+3                ; S_CUOI = (POS = 4) và không hỏng\n        CPL     C\n        ANL     C,/HONG\n        MOV     SCUOI,C\n        ADD     A,#0FFH                 ; CY = 1 khi POS khác 0\n        CPL     C\n        MOV     SDAU,C                  ; S_DAU = (POS = 0)\n        RET\n        END\n","note":"Bấm Từng bước qua vài tick: TMR được nạp 8 khi vào ĐẨY, giảm mỗi tick tới khi POS = 4 làm S_CUOI báo (tick 5); LÙI tương tự tới tick 9. Đoán trước: khi về CHỜ, TMR còn bao nhiêu? (5: LÙI tốn 4 tick, TMR không được nạp lại khi về CHỜ.)","dev":{"led":true},"fosc":12000000,"watch":{"title":"Sơ đồ trạng thái","state":48,"states":["CHỜ","ĐẨY","LÙI","LỖI"],"edges":[[0,1,"START / mở van đẩy, TMR = 8"],[1,2,"S_CUOI / mở van lùi, TMR = 8"],[2,0,"S_DAU / tắt van"],[1,3,"TMR hết / ERR = 1"],[2,3,"TMR hết / ERR = 2"]],"vars":[["TMR",49,"dec"],["POS (mô hình)",51,"dec"],["ERR",50,"hex"],["DEM",52,"dec"],["R7 (tick còn)",7,"dec"]],"hint":"Xi lanh cần 4 tick để ra hết và 4 tick để về; thời hạn mỗi trạng thái là 8 tick. Xem TMR giảm trong lúc chờ và được nạp lại khi vào trạng thái mới."}},{"label":"Lỗi: Thiếu cảm biến cuối, quá thời hạn","code":"; Lỗi: cảm biến cuối hỏng -> quá thời hạn -> LỖI (tiêm lỗi)\n; Van: P1.0 đẩy, P1.1 lùi (0 = bật) · P1.7 đèn lỗi\nSTATE   DATA    30H                     ; 0 CHỜ 1 ĐẨY 2 LÙI 3 LỖI\nTMR     DATA    31H                     ; số tick còn được chờ\nERR     DATA    32H                     ; 1 thiếu S_CUOI, 2 thiếu S_DAU\nPOS     DATA    33H                     ; vị trí xi lanh 0..4 (mô hình)\nDEM     DATA    34H                     ; số phôi đã xong\nHONG    BIT     20H.0                   ; tiêm lỗi: cảm biến cuối hỏng\nSTART   BIT     20H.1                   ; sự kiện nút START\nSCUOI   BIT     20H.2\nSDAU    BIT     20H.3\n        ORG     0000H\n        SETB    HONG                    ; tiêm lỗi: S_CUOI không bao giờ báo\n        SETB    START                   ; người vận hành nhấn START\n        MOV     R7,#16                  ; chạy 16 tick\nBUOC:   ACALL   MOHINH                  ; cập nhật mô hình + cảm biến\n        MOV     A,STATE\n        CJNE    A,#1,K2\n        JB      SCUOI,D_OK              ; ĐẨY: chờ S_CUOI có thời hạn\n        DJNZ    TMR,TIEP\n        MOV     ERR,#1                  ; quá hạn: thiếu S_CUOI\n        SJMP    LOI\nD_OK:   MOV     STATE,#2                ; sang LÙI\n        INC     DEM                     ; phôi đã được đẩy ra\n        MOV     P1,#0FDH                ; đóng đẩy, mở lùi\n        MOV     TMR,#8\n        SJMP    TIEP\nK2:     CJNE    A,#2,K0\n        JB      SDAU,L_OK               ; LÙI: chờ S_DAU có thời hạn\n        DJNZ    TMR,TIEP\n        MOV     ERR,#2\n        SJMP    LOI\nL_OK:   MOV     STATE,#0\n        MOV     P1,#0FFH\n        SJMP    TIEP\nK0:     JNZ     TIEP                    ; LỖI: giữ nguyên, van đã tắt\n        JBC     START,BAT               ; CHỜ: tiêu thụ sự kiện START\n        SJMP    TIEP\nBAT:    MOV     STATE,#1\n        MOV     P1,#0FEH                ; mở van đẩy\n        MOV     TMR,#8                  ; bình thường cần 4 tick\n        SJMP    TIEP\nLOI:    MOV     STATE,#3\n        MOV     P1,#7FH                 ; tắt hai van, bật đèn lỗi\nTIEP:   DJNZ    R7,BUOC\n        SJMP    $\n; --- mô hình xi lanh (giả lập nhà máy, không có trên chip) ---\nMOHINH: MOV     A,POS\n        JB      P1.0,M_LUI              ; van đẩy bật thì ra thêm 1 nấc\n        CJNE    A,#4,$+3\n        ADDC    A,#0                    ; POS < 4 (CY = 1): POS + 1\n        SJMP    M_CB\nM_LUI:  JB      P1.1,M_CB               ; van lùi bật thì về 1 nấc\n        JZ      M_CB\n        DEC     A\nM_CB:   MOV     POS,A\n        CJNE    A,#4,$+3                ; S_CUOI = (POS = 4) và không hỏng\n        CPL     C\n        ANL     C,/HONG\n        MOV     SCUOI,C\n        ADD     A,#0FFH                 ; CY = 1 khi POS khác 0\n        CPL     C\n        MOV     SDAU,C                  ; S_DAU = (POS = 0)\n        RET\n        END\n","note":"Chỉ khác ví dụ 1 một dòng (SETB HONG). POS lên 4 ở tick 5 nhưng S_CUOI không báo; TMR về 0 ở tick 9: máy vào LỖI, ERR = 01H, P1 = 7FH (hai van tắt, đèn lỗi P1.7 sáng) và đứng yên tới hết.","dev":{"led":true},"fosc":12000000,"watch":{"title":"Sơ đồ trạng thái","state":48,"states":["CHỜ","ĐẨY","LÙI","LỖI"],"edges":[[0,1,"START / mở van đẩy, TMR = 8"],[1,2,"S_CUOI / mở van lùi, TMR = 8"],[2,0,"S_DAU / tắt van"],[1,3,"TMR hết / ERR = 1"],[2,3,"TMR hết / ERR = 2"]],"vars":[["TMR",49,"dec"],["POS (mô hình)",51,"dec"],["ERR",50,"hex"],["DEM",52,"dec"]],"hint":"POS đã lên 4 (xi lanh ra hết) nhưng cảm biến hỏng không báo: TMR về 0 ở tick 9, máy vào LỖI, tắt hai van, bật đèn P1.7."}},{"label":"Ví dụ: Interlock là lớp an toàn cuối","code":"; Ví dụ 3: interlock = lớp an toàn cuối trước khi ra cổng\n; Byte thử: 4 bit thấp REQ (bit0 đẩy, bit1 lùi; 1 = muốn bật)\n;           4 bit cao SAFE (bit4 cửa mở, bit5 dừng khẩn)\n; KHOA trả về ACT = các van được phép bật\n        ORG     0000H\n        MOV     R0,#40H                 ; kết quả ghi vào 40H..44H\n        MOV     R7,#0\nLAP:    MOV     A,R7\n        MOV     DPTR,#THU\n        MOVC    A,@A+DPTR\n        ACALL   KHOA\n        MOV     @R0,A\n        INC     R0\n        INC     R7\n        CJNE    R7,#5,LAP\n        SJMP    $\nKHOA:   MOV     B,A\n        ANL     A,#30H                  ; cửa mở hoặc dừng khẩn?\n        JNZ     CAM\n        MOV     A,B\n        ANL     A,#03H                  ; chỉ giữ hai bit van\n        CJNE    A,#03H,DUOC             ; đẩy và lùi cùng lúc?\nCAM:    CLR     A                       ; cấm tất cả\nDUOC:   RET\nTHU:    DB      01H,03H,12H,21H,02H\n        END\n","note":"Chương trình con KHOA chạy cho 5 tình huống (40H…44H): chỉ đẩy → 01H; đẩy + lùi → 00H; cửa mở → 00H; dừng khẩn → 00H; chỉ lùi → 02H. Dừng khẩn và cửa mở được xét trước tiên.","dev":{"led":true},"fosc":12000000,"watch":{"title":"Biến theo dõi","vars":[["R7 (tình huống)",7,"dec"],["ACT 40H",64,"hex"],["ACT 41H",65,"hex"],["ACT 42H",66,"hex"],["ACT 43H",67,"hex"],["ACT 44H",68,"hex"]],"hint":"Năm tình huống: chỉ đẩy → 01H; đẩy + lùi → 00H; cửa mở → 00H; dừng khẩn → 00H; chỉ lùi → 02H."}},{"label":"Bẫy: Tự phục hồi sau lỗi","code":"; Bẫy: tự phục hồi sau lỗi, START là mức (nút bị giữ)\n; Van: P1.0 đẩy, P1.1 lùi (0 = bật) · P1.7 đèn lỗi\nSTATE   DATA    30H                     ; 0 CHỜ 1 ĐẨY 2 LÙI 3 LỖI\nTMR     DATA    31H                     ; số tick còn được chờ\nERR     DATA    32H                     ; 1 thiếu S_CUOI, 2 thiếu S_DAU\nPOS     DATA    33H                     ; vị trí xi lanh 0..4 (mô hình)\nDEM     DATA    34H                     ; số phôi đã xong\nHONG    BIT     20H.0                   ; tiêm lỗi: cảm biến cuối hỏng\nSTART   BIT     20H.1                   ; mức nút START (đang giữ)\nNLOI    DATA    35H                     ; số lần vào LỖI\nSCUOI   BIT     20H.2\nSDAU    BIT     20H.3\n        ORG     0000H\n        SETB    HONG                    ; tiêm lỗi: S_CUOI không bao giờ báo\n        SETB    START                   ; người vận hành nhấn START\n        MOV     R7,#40                  ; chạy 40 tick\nBUOC:   ACALL   MOHINH                  ; cập nhật mô hình + cảm biến\n        MOV     A,STATE\n        CJNE    A,#1,K2\n        JB      SCUOI,D_OK              ; ĐẨY: chờ S_CUOI có thời hạn\n        DJNZ    TMR,TIEP\n        MOV     ERR,#1                  ; quá hạn: thiếu S_CUOI\n        SJMP    LOI\nD_OK:   MOV     STATE,#2                ; sang LÙI\n        INC     DEM                     ; phôi đã được đẩy ra\n        MOV     P1,#0FDH                ; đóng đẩy, mở lùi\n        MOV     TMR,#8\n        SJMP    TIEP\nK2:     CJNE    A,#2,K0\n        JB      SDAU,L_OK               ; LÙI: chờ S_DAU có thời hạn\n        DJNZ    TMR,TIEP\n        MOV     ERR,#2\n        SJMP    LOI\nL_OK:   MOV     STATE,#0\n        MOV     P1,#0FFH\n        SJMP    TIEP\nK0:     JZ      CHO\n        DJNZ    TMR,TIEP                ; SAI: LỖI tự hết sau 2 tick\n        MOV     STATE,#0\n        MOV     P1,#0FFH\n        SJMP    TIEP\nCHO:    JB      START,BAT               ; SAI: mức, không cần nhấn lại\n        SJMP    TIEP\nBAT:    MOV     STATE,#1\n        MOV     P1,#0FEH                ; mở van đẩy\n        MOV     TMR,#8                  ; bình thường cần 4 tick\n        SJMP    TIEP\nLOI:    MOV     STATE,#3\n        MOV     P1,#7FH                 ; tắt hai van, bật đèn lỗi\n        MOV     TMR,#2\n        INC     NLOI\nTIEP:   DJNZ    R7,BUOC\n        SJMP    $\n; --- mô hình xi lanh (giả lập nhà máy, không có trên chip) ---\nMOHINH: MOV     A,POS\n        JB      P1.0,M_LUI              ; van đẩy bật thì ra thêm 1 nấc\n        CJNE    A,#4,$+3\n        ADDC    A,#0                    ; POS < 4 (CY = 1): POS + 1\n        SJMP    M_CB\nM_LUI:  JB      P1.1,M_CB               ; van lùi bật thì về 1 nấc\n        JZ      M_CB\n        DEC     A\nM_CB:   MOV     POS,A\n        CJNE    A,#4,$+3                ; S_CUOI = (POS = 4) và không hỏng\n        CPL     C\n        ANL     C,/HONG\n        MOV     SCUOI,C\n        ADD     A,#0FFH                 ; CY = 1 khi POS khác 0\n        CPL     C\n        MOV     SDAU,C                  ; S_DAU = (POS = 0)\n        RET\n        END\n","note":"LỖI tự về CHỜ sau 2 tick, START đọc theo mức: máy lặp CHỜ → ĐẨY → LỖI ba lần (NLOI = 3), lần nào cũng mở van đẩy vào xi lanh đang kẹt ở cuối. Kết thúc 40 tick máy lại đang ĐẨY.","dev":{"led":true},"fosc":12000000,"watch":{"title":"Sơ đồ trạng thái","state":48,"states":["CHỜ","ĐẨY","LÙI","LỖI"],"edges":[[0,1,"START (mức) / mở van đẩy"],[1,3,"TMR hết / ERR = 1"],[3,0,"SAI: tự về sau 2 tick"],[1,2,"S_CUOI"],[2,0,"S_DAU"]],"vars":[["NLOI",53,"dec"],["TMR",49,"dec"],["POS (mô hình)",51,"dec"],["R7 (tick còn)",7,"dec"]],"hint":"Vòng CHỜ → ĐẨY → LỖI → CHỜ lặp lại 3 lần trong 40 tick: máy liên tục mở van đẩy vào một xi lanh đang kẹt ở cuối hành trình."}},{"label":"Sửa: Chốt lỗi, xác nhận mới phục hồi","code":"; Sửa: chốt lỗi; chỉ phục hồi khi người vận hành xác nhận\n; Van: P1.0 đẩy, P1.1 lùi (0 = bật) · P1.7 đèn lỗi\nSTATE   DATA    30H                     ; 0 CHỜ 1 ĐẨY 2 LÙI 3 LỖI\nTMR     DATA    31H                     ; số tick còn được chờ\nERR     DATA    32H                     ; 1 thiếu S_CUOI, 2 thiếu S_DAU\nPOS     DATA    33H                     ; vị trí xi lanh 0..4 (mô hình)\nDEM     DATA    34H                     ; số phôi đã xong\nHONG    BIT     20H.0                   ; tiêm lỗi: cảm biến cuối hỏng\nSTART   BIT     20H.1                   ; sự kiện nút START\nSCUOI   BIT     20H.2\nSDAU    BIT     20H.3\nACK     BIT     20H.4                   ; sự kiện nút XÁC NHẬN\n        ORG     0000H\n        SETB    HONG                    ; tiêm lỗi: S_CUOI không bao giờ báo\n        SETB    START                   ; người vận hành nhấn START\n        MOV     R7,#24                  ; chạy 24 tick\nBUOC:   CJNE    R7,#12,THAT             ; tick 13: kỹ thuật viên sửa\n        CLR     HONG                    ;   cảm biến rồi nhấn XÁC NHẬN\n        SETB    ACK\nTHAT:   ACALL   MOHINH                  ; cập nhật mô hình + cảm biến\n        MOV     A,STATE\n        CJNE    A,#1,K2\n        JB      SCUOI,D_OK              ; ĐẨY: chờ S_CUOI có thời hạn\n        DJNZ    TMR,TIEP\n        MOV     ERR,#1                  ; quá hạn: thiếu S_CUOI\n        SJMP    LOI\nD_OK:   MOV     STATE,#2                ; sang LÙI\n        INC     DEM                     ; phôi đã được đẩy ra\n        MOV     P1,#0FDH                ; đóng đẩy, mở lùi\n        MOV     TMR,#8\n        SJMP    TIEP\nK2:     CJNE    A,#2,K0\n        JB      SDAU,L_OK               ; LÙI: chờ S_DAU có thời hạn\n        DJNZ    TMR,TIEP\n        MOV     ERR,#2\n        SJMP    LOI\nL_OK:   MOV     STATE,#0\n        MOV     P1,#0FFH\n        SJMP    TIEP\nK0:     JZ      CHO\n        JBC     ACK,XN                  ; LỖI: chỉ thoát khi XÁC NHẬN\n        SJMP    TIEP\nXN:     MOV     ERR,#0                  ; phục hồi: lùi về đầu trước\n        MOV     STATE,#2\n        MOV     P1,#0FDH\n        MOV     TMR,#8\n        SJMP    TIEP\nCHO:\n        JBC     START,BAT               ; CHỜ: cần START mới\n        SJMP    TIEP\nBAT:    MOV     STATE,#1\n        MOV     P1,#0FEH                ; mở van đẩy\n        MOV     TMR,#8                  ; bình thường cần 4 tick\n        SJMP    TIEP\nLOI:    MOV     STATE,#3\n        MOV     P1,#7FH                 ; tắt hai van, bật đèn lỗi\nTIEP:   DJNZ    R7,BUOC\n        SJMP    $\n; --- mô hình xi lanh (giả lập nhà máy, không có trên chip) ---\nMOHINH: MOV     A,POS\n        JB      P1.0,M_LUI              ; van đẩy bật thì ra thêm 1 nấc\n        CJNE    A,#4,$+3\n        ADDC    A,#0                    ; POS < 4 (CY = 1): POS + 1\n        SJMP    M_CB\nM_LUI:  JB      P1.1,M_CB               ; van lùi bật thì về 1 nấc\n        JZ      M_CB\n        DEC     A\nM_CB:   MOV     POS,A\n        CJNE    A,#4,$+3                ; S_CUOI = (POS = 4) và không hỏng\n        CPL     C\n        ANL     C,/HONG\n        MOV     SCUOI,C\n        ADD     A,#0FFH                 ; CY = 1 khi POS khác 0\n        CPL     C\n        MOV     SDAU,C                  ; S_DAU = (POS = 0)\n        RET\n        END\n","note":"LỖI được chốt từ tick 9. Ở tick 13 (giả lập) kỹ thuật viên sửa cảm biến rồi nhấn XÁC NHẬN: máy xóa ERR, lùi xi lanh về đầu (LÙI có thời hạn) rồi đứng ở CHỜ — không tự đẩy lại vì START đã được tiêu thụ.","dev":{"led":true},"fosc":12000000,"watch":{"title":"Sơ đồ trạng thái","state":48,"states":["CHỜ","ĐẨY","LÙI","LỖI"],"edges":[[0,1,"START (sự kiện) / mở van đẩy"],[1,3,"TMR hết / ERR = 1"],[3,2,"XÁC NHẬN / ERR = 0, lùi về đầu"],[1,2,"S_CUOI"],[2,0,"S_DAU / tắt van"]],"vars":[["ERR",50,"hex"],["TMR",49,"dec"],["POS (mô hình)",51,"dec"],["R7 (tick còn)",7,"dec"]],"hint":"LỖI giữ nguyên từ tick 9 tới tick 13 (người vận hành xác nhận sau khi sửa cảm biến); máy lùi xi lanh về đầu rồi đứng ở CHỜ chờ một lần START mới."}},{"label":"Ví dụ: Mất kết nối thì về trạng thái an toàn","code":"; Ví dụ: mất kết nối với máy tính giám sát -> trạng thái an toàn\n; Máy tính gửi nhịp sống (heartbeat) mỗi 2 tick; giả lập: HB\n; tăng ở tick 1, 3, ..., 11 rồi ngừng (rút cáp). 1 vòng = 1 tick\nHB      DATA    30H                     ; bộ đếm nhịp sống nhận qua UART\nLASTHB  DATA    31H                     ; giá trị đã thấy lần trước\nCTO     DATA    32H                     ; số tick còn chờ nhịp sống\nMAT     BIT     20H.0                   ; chốt: đã mất kết nối\n        ORG     0000H\n        MOV     P1,#0FBH                ; động cơ băng tải P1.2 đang chạy\n        MOV     CTO,#6                  ; thời hạn 6 tick = 3 nhịp\n        MOV     R7,#20\nBUOC:   MOV     A,R7                    ; --- giả lập phía máy tính ---\n        CJNE    A,#10,$+3               ; CY = 1 khi R7 < 10: đã rút cáp\n        JC      FW\n        JB      ACC.0,FW                ; gửi khi R7 chẵn (mỗi 2 tick)\n        INC     HB\nFW:     JB      MAT,TIEP                ; --- firmware --- đã an toàn\n        MOV     A,HB\n        CJNE    A,LASTHB,CO             ; có nhịp sống mới?\n        DJNZ    CTO,TIEP                ; chưa: đếm ngược thời hạn\n        SETB    MAT                     ; quá hạn: mất kết nối\n        MOV     P1,#0BFH                ; dừng động cơ, đèn P1.6 báo\n        SJMP    TIEP\nCO:     MOV     LASTHB,A\n        MOV     CTO,#6                  ; nạp lại thời hạn\nTIEP:   DJNZ    R7,BUOC\n        SJMP    $\n        END\n","note":"HB tăng ở tick 1, 3, …, 11 rồi ngừng (rút cáp). CTO được nạp 6 mỗi lần có nhịp sống mới; sau tick 11 nó giảm tới 0 ở tick 17: dừng động cơ P1.2, bật đèn P1.6 (P1 = BFH), chốt MAT.","dev":{"led":true},"fosc":12000000,"watch":{"title":"Biến theo dõi","vars":[["HB",48,"dec"],["LASTHB",49,"dec"],["CTO",50,"dec"],["MAT (20H.0)","20H.0","bit"],["R7 (tick còn)",7,"dec"]],"hint":"Tới tick 11 nhịp sống đến mỗi 2 tick nên CTO luôn được nạp lại; sau đó CTO giảm về 0 ở tick 17: động cơ P1.2 dừng, đèn P1.6 báo mất kết nối, cờ MAT được chốt."}}];
const sim51=makeSim51(document.getElementById("m51-l51"),{id:"s51",presets:P51,ram:256});
makeEx51(document.getElementById("ex-l51"),"l51",[{"t":"Chờ cảm biến có thời hạn","d":"<p>Một bước (chạy mỗi tick) của trạng thái “chờ cảm biến”. Ô <code>30H<\/code> = STATE, <code>31H<\/code> = TMR (số tick còn được chờ, ≥ 1), <code>32H<\/code> = cảm biến (<code>00H<\/code> chưa báo, khác 0 đã báo), <code>33H<\/code> = ERR. Nếu STATE ≠ 1 thì không làm gì. Nếu STATE = 1: cảm biến đã báo thì STATE = 2 (XONG, TMR giữ nguyên); chưa báo thì giảm TMR 1, về 0 thì STATE = 3 (LỖI) và ERR = <code>01H<\/code>. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: STATE = 1, TMR = 5, cảm biến = 0 → TMR = 4, STATE giữ 1.<\/p>","start":"; Một bước \"chờ cảm biến có thời hạn\"\n; 30H STATE (1 = đang chờ) · 31H TMR · 32H cảm biến · 33H ERR\n        ORG     0000H\n        MOV     A,30H\n        CJNE    A,#1,XONG\n        MOV     A,32H\n        JZ      XONG                    ; SAI: chưa có cảm biến thì chờ mãi\n        MOV     30H,#2\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":1,"0x31":5,"0x32":0,"0x33":0}},"expect":{"iram":{"0x30":1,"0x31":4,"0x32":0,"0x33":0}}},{"setup":{"iram":{"0x30":1,"0x31":5,"0x32":1,"0x33":0}},"expect":{"iram":{"0x30":2,"0x31":5,"0x32":1,"0x33":0}}},{"setup":{"iram":{"0x30":1,"0x31":1,"0x32":0,"0x33":0}},"expect":{"iram":{"0x30":3,"0x31":0,"0x32":0,"0x33":1}}},{"setup":{"iram":{"0x30":1,"0x31":1,"0x32":1,"0x33":0}},"expect":{"iram":{"0x30":2,"0x31":1,"0x32":1,"0x33":0}}},{"setup":{"iram":{"0x30":2,"0x31":1,"0x32":0,"0x33":0}},"expect":{"iram":{"0x30":2,"0x31":1,"0x32":0,"0x33":0}}},{"setup":{"iram":{"0x30":3,"0x31":7,"0x32":0,"0x33":1}},"expect":{"iram":{"0x30":3,"0x31":7,"0x32":0,"0x33":1}}},{"setup":{"iram":{"0x30":1,"0x31":2,"0x32":0,"0x33":0}},"expect":{"iram":{"0x30":1,"0x31":1,"0x32":0,"0x33":0}}}]},"hints":["Code mẫu chỉ xét “cảm biến đã báo”: nếu cảm biến hỏng, máy đứng ở STATE = 1 mãi (bộ thử 3).","Nhánh “chưa báo”: DJNZ 31H,… giảm và kiểm về 0 trong một lệnh.","Hết giờ thì vào trạng thái lỗi. Xét cảm biến TRƯỚC khi giảm bộ đếm để cảm biến đến đúng tick cuối vẫn được tính (bộ thử 4)."],"why":"Mọi trạng thái chờ một tín hiệu ngoài đều cần thời hạn; không có thời hạn, một dây cảm biến đứt làm máy treo vĩnh viễn mà không báo gì. Mã lỗi riêng (ERR = 01H: thiếu cảm biến) giúp người sửa máy biết ngay chỗ hỏng."},{"t":"Lớp interlock đầu ra","d":"<p>Yêu cầu từ máy trạng thái ở <code>30H<\/code> (REQ): bit 0 van ĐẨY, bit 1 van LÙI, bit 2 BƠM, bit 7 ĐÈN báo; các bit khác không dùng. Điều kiện an toàn ở <code>31H<\/code> (SAFE): bit 0 cửa che mở, bit 1 dừng khẩn, bit 2 quá nhiệt. Tính <code>32H<\/code> = ACT (các đầu ra được phép) theo quy tắc: dừng khẩn → ACT = <code>80H<\/code> (chỉ đèn báo); ngược lại ACT = REQ chỉ giữ bit 0, 1, 2, 7; cửa mở → xóa bit 0, 1; quá nhiệt → xóa bit 2; nếu bit 0 và bit 1 cùng bằng 1 → xóa cả hai. Ghi ra <code>P1<\/code> = NOT ACT (van và đèn tích cực mức thấp). 30H, 31H giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: REQ = 85H, SAFE = 00H → ACT = 85H, P1 = 7AH.<\/p>","start":"; Lớp interlock đầu ra: 30H REQ, 31H SAFE -> 32H ACT, P1\n        ORG     0000H\n        MOV     A,30H\n        MOV     R2,31H\n        XCH     A,R2                    ; A = SAFE, R2 = REQ\n        JNB     ACC.0,KH                ; cửa mở: cấm đẩy, lùi\n        ANL     02H,#0FCH\nKH:     MOV     A,R2                    ; (chưa có: dừng khẩn, quá nhiệt,\n        JNB     ACC.0,RA                ;  bit không dùng)\n        JNB     ACC.1,RA\n        ANL     A,#0FCH                 ; đẩy và lùi cùng lúc\nRA:     MOV     32H,A\n        MOV     P1,A                    ; SAI: quên đảo cho mức thấp\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":133,"0x31":0}},"expect":{"iram":{"0x30":133,"0x31":0,"0x32":133},"ports":{"P1":122}}},{"setup":{"iram":{"0x30":3,"0x31":0}},"expect":{"iram":{"0x30":3,"0x31":0,"0x32":0},"ports":{"P1":255}}},{"setup":{"iram":{"0x30":135,"0x31":1}},"expect":{"iram":{"0x30":135,"0x31":1,"0x32":132},"ports":{"P1":123}}},{"setup":{"iram":{"0x30":135,"0x31":4}},"expect":{"iram":{"0x30":135,"0x31":4,"0x32":128},"ports":{"P1":127}}},{"setup":{"iram":{"0x30":5,"0x31":2}},"expect":{"iram":{"0x30":5,"0x31":2,"0x32":128},"ports":{"P1":127}}},{"setup":{"iram":{"0x30":122,"0x31":0}},"expect":{"iram":{"0x30":122,"0x31":0,"0x32":2},"ports":{"P1":253}}},{"setup":{"iram":{"0x30":0,"0x31":7}},"expect":{"iram":{"0x30":0,"0x31":7,"0x32":128},"ports":{"P1":127}}},{"setup":{"iram":{"0x30":6,"0x31":5}},"expect":{"iram":{"0x30":6,"0x31":5,"0x32":0},"ports":{"P1":255}}}]},"hints":["Xét dừng khẩn trước tiên: nó thắng mọi quy tắc khác (bộ thử 5, 7).","Dùng ANL A,#87H để bỏ bit không dùng; cửa mở → ANL …,#0FCH; quá nhiệt → ANL …,#0FBH. Kiểm bit của SAFE bằng JNB ACC.n sau khi đưa SAFE vào A.","Quy tắc “đẩy và lùi cùng lúc” xét SAU cùng trên giá trị đã lọc; cuối cùng CPL A trước khi MOV P1,A."],"why":"Interlock là lớp lọc cuối cùng trước cổng ra, chạy mỗi chu kỳ và không phụ thuộc máy trạng thái đang ở đâu: dù máy trạng thái có lỗi logic, hai van ngược chiều không thể cùng mở, cửa mở thì xi lanh không chạy. Đây không thay cho mạch an toàn phần cứng (dừng khẩn phải cắt nguồn động lực bằng mạch riêng)."},{"t":"Chốt lỗi bằng lệnh bit","d":"<p>Các bit trong ô <code>20H<\/code>: bit 0 NEW (lỗi đang có), bit 1 ACK (sự kiện người vận hành nhấn XÁC NHẬN), bit 2 LATCH (lỗi đã chốt), bit 3 RUN (cho phép chạy); bit 4–7 thuộc phần khác, phải giữ nguyên. Quy tắc: LATCH mới = NEW OR (LATCH AND NOT ACK) — xác nhận chỉ bỏ chốt khi lỗi đã hết; RUN = NOT LATCH mới; ACK luôn được xóa (sự kiện đã tiêu thụ); NEW giữ nguyên. Code mẫu dùng nhánh và bỏ chốt sai. Viết lại với chỉ tiêu: không quá <b>13 chu kỳ máy<\/b> (tính cả <code>SJMP $<\/code>) và <b>16 byte<\/b>.<\/p><p>Ví dụ: 20H = 09H (NEW = 1, RUN = 1) → 20H = 05H (LATCH = 1, RUN = 0).<\/p>","start":"; Chốt lỗi và xác nhận (code mẫu: dùng nhánh, có lỗi)\nNEW     BIT     20H.0                   ; lỗi đang có\nACK     BIT     20H.1                   ; sự kiện XÁC NHẬN\nLATCH   BIT     20H.2                   ; lỗi đã chốt\nRUN     BIT     20H.3                   ; cho phép chạy\n        ORG     0000H\n        JNB     NEW,K_ACK\n        SETB    LATCH                   ; có lỗi: chốt\nK_ACK:  JNB     ACK,K_RUN\n        CLR     ACK\n        CLR     LATCH                   ; SAI: xóa chốt cả khi lỗi còn\nK_RUN:  JB      LATCH,CAM\n        SETB    RUN\n        SJMP    XONG\nCAM:    CLR     RUN\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x20":9}},"expect":{"iram":{"0x20":5}}},{"setup":{"iram":{"0x20":6}},"expect":{"iram":{"0x20":8}}},{"setup":{"iram":{"0x20":7}},"expect":{"iram":{"0x20":5}}},{"setup":{"iram":{"0x20":4}},"expect":{"iram":{"0x20":4}}},{"setup":{"iram":{"0x20":0}},"expect":{"iram":{"0x20":8}}},{"setup":{"iram":{"0x20":170}},"expect":{"iram":{"0x20":168}}},{"setup":{"iram":{"0x20":253}},"expect":{"iram":{"0x20":245}}}],"maxCyc":13,"maxBytes":16},"hints":["Chạy code mẫu với bộ thử 3 (NEW = 1, ACK = 1, LATCH = 1): chốt bị bỏ dù lỗi còn — máy được chạy lại khi chưa sửa xong.","Cờ C là “thanh ghi bit”: MOV C,bit; ANL C,bit; ANL C,/bit (AND với bit đảo); ORL C,bit; MOV bit,C. Không cần nhánh.","Viết LATCH mới như một biểu thức logic của LATCH, ACK, NEW; tính trong C bằng lệnh bit. RUN là phần đảo của LATCH."],"why":"Bộ xử lý bit của 8051 tính biểu thức logic trên từng bit trực tiếp trong RAM vùng bit, không đụng tới các bit khác của byte 20H và không rẽ nhánh: thời gian luôn là 13 chu kỳ. Quy tắc LATCH = NEW OR (LATCH AND NOT ACK) là “phục hồi có chủ đích”: lỗi chỉ được bỏ khi đã hết và có người xác nhận."}]);

/* Bảng “Sơ đồ trạng thái” của Chương 13 (sinh bởi tools/author/mcu8051/m13lib.py): đọc RAM của máy giả lập, không đổi trình mô phỏng. */
(function(){const R=document.getElementById("m51-l51"),PS=P51,H2=v=>v.toString(16).toUpperCase().padStart(2,"0");let pi=-1,sec=null,last=null,prevS=null,edge=-1,seen=null;
 function rd(m,a){if(typeof a==="string"){const x=/^([0-9A-F]+)H\.([0-7])$/i.exec(a);return x?(m.iram[parseInt(x[1],16)]>>+x[2])&1:0}return a>=0x80&&a<0x100&&PS[pi].watch.sfr?m.sfr[a-0x80]:m.iram[a]}
 function shape(w){if(!sec){sec=document.createElement("section");sec.className="pn m13-w";sec.innerHTML='<div class="pane-h"><span>Sơ đồ trạng thái</span><span class="m13-h"></span></div><div class="m51-sec m13-b"></div>';}
  const sc=R.querySelector(".st-scroll");if(sec.parentNode!==sc)sc.insertBefore(sec,sc.firstChild);sec.hidden=!w;if(!w)return;
  sec.querySelector(".pane-h span").textContent=w.title||"Sơ đồ trạng thái";
  let h="";if(w.states)h+='<div class="m13-st" role="list" aria-label="Các trạng thái">'+w.states.map((s,i)=>'<span class="s" role="listitem" data-s="'+i+'">'+s+'</span>').join("")+'</div>';
  if(w.edges)h+='<ul class="m13-ed">'+w.edges.map((e,i)=>'<li data-e="'+i+'">'+w.states[e[0]]+' → '+w.states[e[1]]+': '+e[2]+'</li>').join("")+'</ul>';
  if(w.vars)h+='<div class="m13-vr">'+w.vars.map((v,i)=>'<span data-v="'+i+'"><b>'+v[0]+'</b> <i>–</i></span>').join("")+'</div>';
  h+='<p class="m13-hint">'+(w.hint||"Trạng thái và biến đọc từ RAM trong sau mỗi lệnh; ô vừa đổi được tô màu.")+'</p>';
  sec.querySelector(".m13-b").innerHTML=h;last=null;prevS=null;edge=-1;seen=null}
 function paint(m){const w=PS[pi].watch;if(!w)return;const H=sec.querySelector(".m13-h");
  if(!m){H.textContent="chưa chạy";sec.querySelectorAll(".m13-st .s").forEach(x=>x.classList.remove("on","was"));sec.querySelectorAll(".m13-ed li").forEach(x=>x.classList.remove("on"));sec.querySelectorAll(".m13-vr i").forEach(x=>x.textContent="–");last=null;prevS=null;edge=-1;return}
  if(m!==seen){seen=m;last=null;prevS=null;edge=-1}
  const vals=(w.vars||[]).map(v=>rd(m,v[1]));
  if(w.states){const s=rd(m,w.state);if(prevS!=null&&s!==prevS&&w.edges){const k=w.edges.findIndex(e=>e[0]===prevS&&e[1]===s);if(k>=0)edge=k}
   sec.querySelectorAll(".m13-st .s").forEach(x=>{x.classList.toggle("on",+x.dataset.s===s);x.classList.toggle("was",prevS!=null&&+x.dataset.s===prevS&&s!==prevS)});
   sec.querySelectorAll(".m13-ed li").forEach(x=>x.classList.toggle("on",+x.dataset.e===edge));
   H.textContent=s<w.states.length?"trạng thái "+s+" · "+w.states[s].replace(/<[^>]+>/g,""):"trạng thái "+H2(s)+"H (ngoài bảng!)";if(s!==prevS)prevS=s}
  else H.textContent="t = "+(m.cyc*12/m.fosc*1000).toLocaleString("vi-VN",{maximumFractionDigits:3})+" ms";
  sec.querySelectorAll(".m13-vr span").forEach((x,i)=>{const v=vals[i],k=w.vars[i][2]||"hex";x.querySelector("i").textContent=k==="dec"?String(v):k==="bit"?String(v):H2(v)+"H ("+v+")";x.classList.toggle("chg",!!last&&last[i]!==v)});last=vals}
 function loop(){const sc=R&&R.querySelector(".st-scroll");if(sc){const sel=R.querySelector(".s-pre"),i=sel?+sel.value:0;
   if(i!==pi){pi=i;const p=PS[i]||{};const sp=R.querySelector(".m51-sp");if(sp&&p.speed)sp.value=p.speed;shape(p.watch);sec&&(seen=null)}
   else if(sec&&sec.parentNode!==sc)shape(PS[pi].watch);
   if(PS[pi]&&PS[pi].watch){let m=null;try{m=sim51.machine()}catch(e){}paint(m)}}
  setTimeout(loop,150)}
 if(R)loop()})();

